def hook(ctx, nb):
    stage = nb.get('stage')
    msg = ''
    if stage == 'need_schema_probe':
        msg = 'Schema recovery: use SHOW TABLES, then DESCRIBE the exact table name returned. Backtick identifiers with spaces or punctuation; do not invent underscore names.'
    elif stage == 'fixing_empty_result':
        msg = 'Empty SELECT recovery: inspect sample rows or distinct values for the filtered columns, then relax one predicate or use LIKE to find the stored format before retrying.'
    elif stage == 'repeated_query_loop':
        msg = 'Repeated SQL loop: change strategy by probing schema, inspecting sample values, or simplifying predicates instead of rerunning the same query.'
    elif stage == 'text_numeric_handling':
        msg = 'Text numeric handling: for ranking, sorting, or aggregation over numeric-looking text, remove currency/percent/symbol formatting and CAST to SIGNED or DECIMAL before comparing.'
    elif stage == 'mutation_needs_execution':
        msg = 'Mutation task: first execute the INSERT, UPDATE, or DELETE. An empty result from a data-changing statement can still mean it ran; verify afterward.'
    elif stage == 'ready_to_commit_candidate':
        msg = 'Mutation verification: run a SELECT on the target row(s) to confirm the changed columns and exact stored text, including spaces, punctuation, currency, percent signs, and newlines, before committing.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

def hook(ctx, nb):
    a = ctx.get('action') or {}
    p = ctx.get('predicates') or {}
    if a.get('tool') != 'commit_final_answer':
        return None
    if p.get('commit_before_sql') or p.get('no_sql_yet'):
        return {'kind': 'block_and_prompt', 'message': 'Run at least one SQL query to inspect or modify the database before committing a final answer.'}
    if p.get('commit_empty_answer') and not (p.get('mutation_task') and (nb.get('stage') == 'ready_to_commit_candidate' or nb.get('mutation_needs_execution'))):
        return {'kind': 'block_and_prompt', 'message': 'Do not commit an empty answer list for a SELECT-style task; provide the SQL-derived values in the requested shape.'}
    if p.get('mutation_task') and p.get('mutation_not_attempted') and not (p.get('remaining_rounds_low') and nb.get('stage') == 'need_schema_probe'):
        return {'kind': 'block_and_prompt', 'message': 'This is a data-changing task, but no INSERT, UPDATE, or DELETE has been executed yet. Perform the mutation and verify it before committing.'}
    return None
